template<typename Visitor> void walkReferences(const CreatorRecord& subject, Visitor& visitor) { walkCreatorRecord(subject, visitor); }
template<typename Visitor> void forEachReference(CreatorRecord& subject, Visitor&& visitor) { walkWithoutRoles(subject, visitor); }
