template<typename Subject, typename Visitor>
void walkDataNode(Subject& variant, Visitor& visitor)
{
    switch (variant.kind()) {
    case DataNode::Kind::Undefined: case DataNode::Kind::Null: case DataNode::Kind::Hole: case DataNode::Kind::Boolean: case DataNode::Kind::Number:
        return;
    case DataNode::Kind::String:
        {
            auto& value = variant.template as<DataNode::String>();
            visitReference(value.value, visitor);
            return;
        }
    case DataNode::Kind::BigInt:
        {
            auto& value = variant.template as<DataNode::BigInt>();
            visitReference(value.digits, visitor);
            return;
        }
    case DataNode::Kind::Array:
        {
            auto& value = variant.template as<DataNode::Array>();
            visitReference(value.contents, visitor);
            for (auto& element : value.elements)
                walkReferences(element, visitor);
            return;
        }
    case DataNode::Kind::Object:
        {
            auto& value = variant.template as<DataNode::Object>();
            visitReference(value.layout, visitor);
            for (auto& element : value.members)
                walkReferences(element, visitor);
            return;
        }
    }
    RELEASE_ASSERT_NOT_REACHED();
}

